INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-0-0', 'essential that', 'esencial que', 'esénshal dat', 'It is essential that everyone participate.', 'Es esencial que todos participen.', '📜');
