INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-0-1', 41, 2, 'learn', 'Unidad 2: Cláusulas participiales', 'Reconocer, pronunciar y usar «having finished» y «given the» en contexto (Advanced Grammar Structures).', 'En esta unidad de Advanced Grammar Structures trabajarás «having finished» y «given the». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-0-1', 'having finished', 'habiendo terminado', 'jáving fínisht', 'Having finished the audit, she left.', 'Habiendo terminado la auditoría, se retiró.', '📂');
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-0-1', 'given the', 'dado el / dada la', 'guíven de', 'Given the timeline, we must prioritize.', 'Dado el cronograma, debemos priorizar.', '⏳');
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-0-2', 41, 3, 'final', 'Unidad 3: Estructuras con Rather y Wish', 'Reconocer, pronunciar y usar «would rather» y «wish» en contexto (Advanced Grammar Structures).', 'En esta unidad de Advanced Grammar Structures trabajarás «would rather» y «wish». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-0-2', 'would rather', 'preferiría', 'uúd ráder', 'I would rather review the draft first.', 'Preferiría revisar el borrador primero.', '✍️');
