INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-1-0', 42, 1, 'learn', 'Unidad 1: Inversión con adverbios negativos', 'Reconocer, pronunciar y usar «never have» y «rarely does» en contexto (Inversion and Emphasis).', 'En esta unidad de Inversion and Emphasis trabajarás «never have» y «rarely does». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-1-0', 'never have', 'nunca he / jamás he', 'néver jáv', 'Never have I seen such dedication.', 'Jamás he visto tanta dedicación.', '🌟');
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-1-0', 'rarely does', 'rara vez', 'rérli dás', 'Rarely does an opportunity arise twice.', 'Rara vez surge una oportunidad dos veces.', '💎');
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-1-1', 42, 2, 'learn', 'Unidad 2: Not only... but also', 'Reconocer, pronunciar y usar «not only» y «seldom» en contexto (Inversion and Emphasis).', 'En esta unidad de Inversion and Emphasis trabajarás «not only» y «seldom». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-1-1', 'not only', 'no solo', 'nót óunli', 'Not only did he lead, but he inspired.', 'No solo lideró, sino que inspiró.', '🎯');
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-1-1', 'seldom', 'pocas veces', 'séldom', 'Seldom have results been so consistent.', 'Pocas veces los resultados han sido tan consistentes.', '📈');
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-1-2', 42, 3, 'final', 'Unidad 3: Énfasis con Only y Little', 'Reconocer, pronunciar y usar «only when» y «little did» en contexto (Inversion and Emphasis).', 'En esta unidad de Inversion and Emphasis trabajarás «only when» y «little did». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-1-2', 'only when', 'solo cuando', 'óunli uén', 'Only when you practice does fluency grow.', 'Solo cuando practicas crece la fluidez.', '🌱');
