INSERT INTO topics (id, level_id, topic_order, name) VALUES (43, 2, 3, 'Mixed Conditionals') ON CONFLICT (level_id, topic_order) DO UPDATE SET name = EXCLUDED.name;
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-2-0', 43, 1, 'learn', 'Unidad 1: Pasado irreal con resultado presente', 'Reconocer, pronunciar y usar «would be» y «had studied» en contexto (Mixed Conditionals).', 'En esta unidad de Mixed Conditionals trabajarás «would be» y «had studied». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-2-0', 'would be', 'sería / estaría', 'uúd bí', 'If I had slept earlier, I would be rested now.', 'Si hubiera dormido más temprano, estaría descansado ahora.', '⚡');
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-2-0', 'had studied', 'hubiera estudiado', 'jád stádid', 'If she had studied law, she would work here now.', 'Si hubiera estudiado derecho, trabajaría aquí ahora.', '⚖️');
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-2-1', 43, 2, 'learn', 'Unidad 2: Presente irreal con resultado pasado', 'Reconocer, pronunciar y usar «would have» y «were not» en contexto (Mixed Conditionals).', 'En esta unidad de Mixed Conditionals trabajarás «would have» y «were not». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-2-1', 'would have', 'habría', 'uúd jáv', 'If he were more organized, he would have finished.', 'Si fuera más organizado, habría terminado.', '📋');
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-2-1', 'were not', 'no fuera', 'uér nót', 'If it were not so costly, we would have bought it.', 'Si no fuera tan costoso, lo habríamos comprado.', '💼');
INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-2-2', 43, 3, 'final', 'Unidad 3: Condicionales formales invertidos', 'Reconocer, pronunciar y usar «had we» y «should you» en contexto (Mixed Conditionals).', 'En esta unidad de Mixed Conditionals trabajarás «had we» y «should you». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-2-2', 'had we', 'si hubiéramos', 'jád uí', 'Had we acted sooner, losses would be smaller.', 'Si hubiéramos actuado antes, las pérdidas serían menores.', '📉');
