INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-3-0', 'must have', 'debe haber', 'mást jáv', 'She must have practiced for months.', 'Ella debe haber practicado durante meses.', '🏆');
