INSERT INTO vocabulary_items (unit_id, word_en, meaning_es, phonetic, example_en, example_es, emoji) VALUES ('l-2-6-1', 'demonstrate', 'demostrar', 'démonstreit', 'The findings demonstrate a clear correlation.', 'Los hallazgos demuestran una correlación clara.', '📈');
