INSERT INTO units (id, topic_id, unit_order, kind, title, objective, intro_text) VALUES ('l-2-6-2', 47, 3, 'final', 'Unidad 3: Cohesión y tono objetivo', 'Reconocer, pronunciar y usar «consequently» y «furthermore» en contexto (Academic Writing and Formal Language).', 'En esta unidad de Academic Writing and Formal Language trabajarás «consequently» y «furthermore». Escucha cada audio, repite en voz alta y completa los ejercicios.') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
