-- ============================================================================
-- CHILO ENGLISH - 01_schema.sql (PostgreSQL 15+ / Supabase)
-- 18 Tablas normalizadas con restricciones, índices y relaciones
-- ============================================================================
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 1. Usuarios y control de acceso
CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username VARCHAR(60) UNIQUE NOT NULL,
    email VARCHAR(160) UNIQUE NOT NULL,
    full_name VARCHAR(120) NOT NULL,
    preferred_name VARCHAR(60),
    role VARCHAR(20) NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'moderator', 'admin')),
    password_hash TEXT NOT NULL,
    password_salt TEXT NOT NULL,
    english_level VARCHAR(20) NOT NULL DEFAULT 'Principiante' CHECK (english_level IN ('Principiante', 'Intermedio', 'Avanzado')),
    voice_accent VARCHAR(10) NOT NULL DEFAULT 'en-US' CHECK (voice_accent IN ('en-US', 'en-GB')),
    visual_theme VARCHAR(20) NOT NULL DEFAULT 'classic',
    ranking_visible BOOLEAN NOT NULL DEFAULT TRUE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    failed_login_attempts INTEGER NOT NULL DEFAULT 0,
    locked_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Sesiones activas
CREATE TABLE IF NOT EXISTS user_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash TEXT UNIQUE NOT NULL,
    device_label VARCHAR(120),
    ip_address INET,
    user_agent TEXT,
    is_revoked BOOLEAN NOT NULL DEFAULT FALSE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Tokens de recuperación de contraseña
CREATE TABLE IF NOT EXISTS password_reset_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash TEXT UNIQUE NOT NULL,
    used BOOLEAN NOT NULL DEFAULT FALSE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Cuestionario de bienvenida de Chilo (10 preguntas)
CREATE TABLE IF NOT EXISTS onboarding_answers (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    preferred_name VARCHAR(60),
    age_private INTEGER CHECK (age_private IS NULL OR (age_private BETWEEN 5 AND 110)),
    country VARCHAR(80),
    main_language VARCHAR(60),
    learning_reason VARCHAR(120),
    self_level VARCHAR(40),
    focus_skill VARCHAR(60),
    daily_time VARCHAR(40),
    learning_style VARCHAR(60),
    main_goal VARCHAR(120),
    completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 5. Currículo: Niveles, Temas, Unidades y Vocabulario
CREATE TABLE IF NOT EXISTS levels (
    id SMALLINT PRIMARY KEY,
    code VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(40) NOT NULL UNIQUE,
    description TEXT NOT NULL,
    total_topics INTEGER NOT NULL,
    total_units INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS topics (
    id SERIAL PRIMARY KEY,
    level_id SMALLINT NOT NULL REFERENCES levels(id) ON DELETE CASCADE,
    topic_order SMALLINT NOT NULL,
    name VARCHAR(120) NOT NULL,
    UNIQUE(level_id, topic_order)
);

CREATE TABLE IF NOT EXISTS units (
    id VARCHAR(24) PRIMARY KEY,
    topic_id INTEGER NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    unit_order SMALLINT NOT NULL,
    kind VARCHAR(16) NOT NULL CHECK (kind IN ('learn', 'review', 'final')),
    title VARCHAR(160) NOT NULL,
    objective TEXT NOT NULL,
    intro_text TEXT NOT NULL,
    UNIQUE(topic_id, unit_order)
);

CREATE TABLE IF NOT EXISTS vocabulary_items (
    id SERIAL PRIMARY KEY,
    unit_id VARCHAR(24) NOT NULL REFERENCES units(id) ON DELETE CASCADE,
    word_en VARCHAR(120) NOT NULL,
    meaning_es VARCHAR(160) NOT NULL,
    phonetic VARCHAR(120) NOT NULL,
    example_en TEXT NOT NULL,
    example_es TEXT NOT NULL,
    emoji VARCHAR(16)
);

-- 6. Progreso y estadísticas
CREATE TABLE IF NOT EXISTS user_lesson_progress (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    unit_id VARCHAR(24) NOT NULL REFERENCES units(id) ON DELETE CASCADE,
    completed BOOLEAN NOT NULL DEFAULT FALSE,
    current_step SMALLINT NOT NULL DEFAULT 0,
    accuracy_pct SMALLINT NOT NULL DEFAULT 0 CHECK (accuracy_pct BETWEEN 0 AND 100),
    xp_earned INTEGER NOT NULL DEFAULT 0,
    duration_sec INTEGER NOT NULL DEFAULT 0,
    completed_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, unit_id)
);

CREATE TABLE IF NOT EXISTS user_stats (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    total_xp INTEGER NOT NULL DEFAULT 0,
    leaves_balance INTEGER NOT NULL DEFAULT 0 CHECK (leaves_balance >= 0),
    streak_days INTEGER NOT NULL DEFAULT 0,
    last_activity_date DATE
);

-- 7. Logros
CREATE TABLE IF NOT EXISTS achievements_catalog (
    id VARCHAR(50) PRIMARY KEY,
    category VARCHAR(40) NOT NULL,
    title VARCHAR(100) NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS user_achievements (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    achievement_id VARCHAR(50) NOT NULL REFERENCES achievements_catalog(id) ON DELETE CASCADE,
    unlocked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, achievement_id)
);

-- 8. Centro de Audios
CREATE TABLE IF NOT EXISTS audio_categories (
    id SERIAL PRIMARY KEY,
    slug VARCHAR(60) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    sort_order SMALLINT NOT NULL
);

CREATE TABLE IF NOT EXISTS audio_favorites (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    vocab_id INTEGER NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, vocab_id)
);

-- 9. Jardín Virtual 3D, Tienda, Inventario y Transacciones
CREATE TABLE IF NOT EXISTS garden_shop_catalog (
    id VARCHAR(50) PRIMARY KEY,
    item_kind VARCHAR(20) NOT NULL CHECK (item_kind IN ('flower', 'plant', 'shrub', 'tree', 'decor', 'fertilizer')),
    name VARCHAR(100) NOT NULL,
    leaf_cost INTEGER NOT NULL CHECK (leaf_cost >= 0),
    stages_json JSONB,
    description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS garden_inventory (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    item_id VARCHAR(50) NOT NULL REFERENCES garden_shop_catalog(id) ON DELETE CASCADE,
    quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    PRIMARY KEY (user_id, item_id)
);

CREATE TABLE IF NOT EXISTS garden_plots (
    id SERIAL PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    plot_index SMALLINT NOT NULL CHECK (plot_index BETWEEN 0 AND 24),
    item_id VARCHAR(50) REFERENCES garden_shop_catalog(id),
    growth_stage SMALLINT NOT NULL DEFAULT 0 CHECK (growth_stage BETWEEN 0 AND 3),
    hydration SMALLINT NOT NULL DEFAULT 100 CHECK (hydration BETWEEN 0 AND 100),
    fertilized BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, plot_index)
);

CREATE TABLE IF NOT EXISTS garden_transactions (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tx_type VARCHAR(20) NOT NULL CHECK (tx_type IN ('earn', 'spend', 'harvest')),
    leaves_delta INTEGER NOT NULL,
    item_id VARCHAR(50),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 10. Juegos Educativos
CREATE TABLE IF NOT EXISTS game_sessions (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    game_category VARCHAR(60) NOT NULL,
    variant_number INTEGER NOT NULL DEFAULT 1,
    score INTEGER NOT NULL DEFAULT 0,
    accuracy_pct SMALLINT NOT NULL DEFAULT 0,
    leaves_rewarded INTEGER NOT NULL DEFAULT 0,
    played_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 11. Foros Educativos y Moderación
CREATE TABLE IF NOT EXISTS forum_posts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    category VARCHAR(40) NOT NULL,
    title VARCHAR(140) NOT NULL,
    body TEXT NOT NULL,
    is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS forum_replies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    post_id UUID NOT NULL REFERENCES forum_posts(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    body TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS forum_reports (
    id BIGSERIAL PRIMARY KEY,
    post_id UUID NOT NULL REFERENCES forum_posts(id) ON DELETE CASCADE,
    reporter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reason TEXT NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'reviewed', 'dismissed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 12. Seguridad, Auditoría y Rate Limiting
CREATE TABLE IF NOT EXISTS security_audit_logs (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    event_type VARCHAR(60) NOT NULL,
    severity VARCHAR(16) NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warning', 'critical')),
    ip_address INET,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS rate_limits (
    rate_key VARCHAR(160) PRIMARY KEY,
    attempts INTEGER NOT NULL DEFAULT 0,
    window_start TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    blocked_until TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_progress_user ON user_lesson_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON user_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_user ON security_audit_logs(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_details_gin ON security_audit_logs USING GIN (details);
CREATE INDEX IF NOT EXISTS idx_vocab_unit ON vocabulary_items(unit_id);

-- ============================================================================
-- CHILO ENGLISH - 02_rls_policies.sql
-- Políticas de Row Level Security (RLS) por usuario y rol
-- ============================================================================
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE password_reset_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE onboarding_answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_lesson_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_stats ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_achievements ENABLE ROW LEVEL SECURITY;
ALTER TABLE audio_favorites ENABLE ROW LEVEL SECURITY;
ALTER TABLE garden_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE garden_plots ENABLE ROW LEVEL SECURITY;
ALTER TABLE garden_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE game_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE forum_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE forum_replies ENABLE ROW LEVEL SECURITY;
ALTER TABLE forum_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE security_audit_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY users_self_select ON users FOR SELECT USING (auth.uid() = id);
CREATE POLICY users_self_update ON users FOR UPDATE USING (auth.uid() = id);
CREATE POLICY sessions_owner ON user_sessions FOR ALL USING (auth.uid() = user_id);
CREATE POLICY reset_owner ON password_reset_tokens FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY onboarding_owner ON onboarding_answers FOR ALL USING (auth.uid() = user_id);
CREATE POLICY progress_owner ON user_lesson_progress FOR ALL USING (auth.uid() = user_id);
CREATE POLICY stats_owner ON user_stats FOR ALL USING (auth.uid() = user_id);
CREATE POLICY achievements_owner ON user_achievements FOR ALL USING (auth.uid() = user_id);
CREATE POLICY audio_fav_owner ON audio_favorites FOR ALL USING (auth.uid() = user_id);
CREATE POLICY garden_inv_owner ON garden_inventory FOR ALL USING (auth.uid() = user_id);
CREATE POLICY garden_plots_owner ON garden_plots FOR ALL USING (auth.uid() = user_id);
CREATE POLICY garden_tx_owner ON garden_transactions FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY games_owner ON game_sessions FOR ALL USING (auth.uid() = user_id);

CREATE POLICY forum_read_visible ON forum_posts FOR SELECT USING (is_hidden = FALSE OR auth.uid() = user_id);
CREATE POLICY forum_insert_auth ON forum_posts FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY forum_delete_owner ON forum_posts FOR DELETE USING (auth.uid() = user_id);
CREATE POLICY replies_read_all ON forum_replies FOR SELECT USING (TRUE);
CREATE POLICY replies_insert_auth ON forum_replies FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY reports_insert_auth ON forum_reports FOR INSERT WITH CHECK (auth.uid() = reporter_id);

CREATE POLICY audit_self_read ON security_audit_logs FOR SELECT USING (auth.uid() = user_id);

-- ============================================================================
-- CHILO ENGLISH - 03_triggers_audit.sql
-- Triggers de integridad, auditoría de seguridad y recompensas automáticas
-- ============================================================================
CREATE OR REPLACE FUNCTION fn_touch_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at
BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

DROP TRIGGER IF EXISTS trg_progress_updated_at ON user_lesson_progress;
CREATE TRIGGER trg_progress_updated_at
BEFORE UPDATE ON user_lesson_progress FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

DROP TRIGGER IF EXISTS trg_garden_plots_updated_at ON garden_plots;
CREATE TRIGGER trg_garden_plots_updated_at
BEFORE UPDATE ON garden_plots FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

CREATE OR REPLACE FUNCTION fn_init_user_stats()
RETURNS TRIGGER AS $$
BEGIN
    VALUES (NEW.id, 0, 5, 0)
    ON CONFLICT (user_id) DO NOTHING;

    VALUES (NEW.id, 'ACCOUNT_CREATED', 'info', jsonb_build_object('role', NEW.role));
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_init_user_stats ON users;
CREATE TRIGGER trg_init_user_stats
AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION fn_init_user_stats();

CREATE OR REPLACE FUNCTION fn_audit_password_change()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.password_hash IS DISTINCT FROM OLD.password_hash THEN
        VALUES (NEW.id, 'PASSWORD_CHANGED', 'warning', jsonb_build_object('changed_at', NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_audit_password_change ON users;
CREATE TRIGGER trg_audit_password_change
AFTER UPDATE ON users FOR EACH ROW EXECUTE FUNCTION fn_audit_password_change();

-- ============================================================================
-- CHILO ENGLISH - 04_stored_procedures.sql
-- Procedimientos almacenados transaccionales y de seguridad
-- ============================================================================

-- 1. Registrar intento de inicio de sesión con bloqueo tras 5 fallos (15 min)
CREATE OR REPLACE FUNCTION sp_record_login_attempt(
    p_user_id UUID,
    p_success BOOLEAN,
    p_ip INET DEFAULT NULL
) RETURNS TABLE(is_locked BOOLEAN, locked_until TIMESTAMPTZ) AS $$
DECLARE
    v_attempts INTEGER;
    v_locked_until TIMESTAMPTZ;
BEGIN
    IF p_success THEN
        UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE id = p_user_id;
        VALUES (p_user_id, 'LOGIN_SUCCESS', 'info', p_ip);
        RETURN QUERY SELECT FALSE, NULL::TIMESTAMPTZ;
    ELSE
        UPDATE users
        SET failed_login_attempts = failed_login_attempts + 1,
            locked_until = CASE WHEN failed_login_attempts + 1 >= 5 THEN NOW() + INTERVAL '15 minutes' ELSE locked_until END
        WHERE id = p_user_id
        RETURNING failed_login_attempts, users.locked_until INTO v_attempts, v_locked_until;

        VALUES (p_user_id, 'LOGIN_FAILED', 'warning', p_ip, jsonb_build_object('attempts', v_attempts));

        RETURN QUERY SELECT (v_locked_until IS NOT NULL AND v_locked_until > NOW()), v_locked_until;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- 2. Completar unidad de aprendizaje y otorgar XP + Hojas + Racha
CREATE OR REPLACE FUNCTION sp_complete_lesson_unit(
    p_user_id UUID,
    p_unit_id VARCHAR(24),
    p_accuracy SMALLINT,
    p_xp INTEGER,
    p_duration_sec INTEGER
) RETURNS VOID AS $$
DECLARE
    v_already_done BOOLEAN;
    v_leaves_reward INTEGER := 2;
BEGIN
    SELECT completed INTO v_already_done
    FROM user_lesson_progress
    WHERE user_id = p_user_id AND unit_id = p_unit_id;

    VALUES (p_user_id, p_unit_id, TRUE, p_accuracy, p_xp, p_duration_sec, NOW())
    ON CONFLICT (user_id, unit_id) DO UPDATE SET
        completed = TRUE,
        accuracy_pct = GREATEST(user_lesson_progress.accuracy_pct, EXCLUDED.accuracy_pct),
        xp_earned = user_lesson_progress.xp_earned + EXCLUDED.xp_earned,
        duration_sec = user_lesson_progress.duration_sec + EXCLUDED.duration_sec,
        completed_at = COALESCE(user_lesson_progress.completed_at, NOW());

    IF NOT COALESCE(v_already_done, FALSE) THEN
        UPDATE user_stats
        SET total_xp = total_xp + p_xp,
            leaves_balance = leaves_balance + v_leaves_reward,
            streak_days = CASE
                WHEN last_activity_date = CURRENT_DATE THEN streak_days
                WHEN last_activity_date = CURRENT_DATE - 1 THEN streak_days + 1
                ELSE 1
            END,
            last_activity_date = CURRENT_DATE
        WHERE user_id = p_user_id;

        VALUES (p_user_id, 'earn', v_leaves_reward, p_unit_id);
    END IF;
END;
$$ LANGUAGE plpgsql;

-- 3. Compra atómica en la Tienda del Jardín 3D
CREATE OR REPLACE FUNCTION sp_buy_garden_item(
    p_user_id UUID,
    p_item_id VARCHAR(50),
    p_qty INTEGER DEFAULT 1
) RETURNS INTEGER AS $$
DECLARE
    v_cost INTEGER;
    v_balance INTEGER;
    v_total INTEGER;
BEGIN
    IF p_qty <= 0 THEN RAISE EXCEPTION 'Cantidad inválida'; END IF;
    SELECT leaf_cost INTO v_cost FROM garden_shop_catalog WHERE id = p_item_id;
    IF v_cost IS NULL THEN RAISE EXCEPTION 'Artículo no encontrado en catálogo'; END IF;

    v_total := v_cost * p_qty;
    SELECT leaves_balance INTO v_balance FROM user_stats WHERE user_id = p_user_id FOR UPDATE;
    IF v_balance < v_total THEN RAISE EXCEPTION 'Saldo de hojas insuficiente'; END IF;

    UPDATE user_stats SET leaves_balance = leaves_balance - v_total WHERE user_id = p_user_id RETURNING leaves_balance INTO v_balance;

    VALUES (p_user_id, p_item_id, p_qty)
    ON CONFLICT (user_id, item_id) DO UPDATE SET quantity = garden_inventory.quantity + EXCLUDED.quantity;

    VALUES (p_user_id, 'spend', -v_total, p_item_id);

    RETURN v_balance;
END;
$$ LANGUAGE plpgsql;

-- 4. Revocar todas las sesiones activas de un usuario
CREATE OR REPLACE FUNCTION sp_revoke_all_sessions(p_user_id UUID) RETURNS INTEGER AS $$
DECLARE v_count INTEGER;
BEGIN
    UPDATE user_sessions SET is_revoked = TRUE WHERE user_id = p_user_id AND is_revoked = FALSE;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    VALUES (p_user_id, 'SESSIONS_REVOKED', 'warning', jsonb_build_object('revoked_count', v_count));
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

-- 5. Exportar respaldo completo en JSONB por usuario
CREATE OR REPLACE FUNCTION sp_export_user_backup(p_user_id UUID) RETURNS JSONB AS $$
BEGIN
    RETURN jsonb_build_object(
        'exported_at', NOW(),
        'profile', (SELECT row_to_json(u) FROM (SELECT id, username, email, full_name, preferred_name, english_level, voice_accent FROM users WHERE id = p_user_id) u),
        'stats', (SELECT row_to_json(s) FROM user_stats s WHERE s.user_id = p_user_id),
        'onboarding', (SELECT row_to_json(o) FROM onboarding_answers o WHERE o.user_id = p_user_id),
        'progress', COALESCE((SELECT jsonb_agg(row_to_json(p)) FROM user_lesson_progress p WHERE p.user_id = p_user_id), '[]'::jsonb),
        'garden_plots', COALESCE((SELECT jsonb_agg(row_to_json(g)) FROM garden_plots g WHERE g.user_id = p_user_id), '[]'::jsonb),
        'achievements', COALESCE((SELECT jsonb_agg(row_to_json(a)) FROM user_achievements a WHERE a.user_id = p_user_id), '[]'::jsonb)
    );
END;
$$ LANGUAGE plpgsql;

